/*
 * attack_harness.c -- REDTEAM memstr adversarial harness.
 *
 * Reads results/attack_cases.tsv (generated by attack_cases.py, fixed seed)
 * and executes EVERY case in a FORKED CHILD, so a crash/corruption cannot kill
 * the harness.  A pipe carries the child's observed return code + canary
 * result back to the parent before it _exit()s with a classification code.
 *
 * Outcome classes (mutually exclusive, precedence CRASH > CORRUPT >
 * UNEXPECTED_OK > REFUSED):
 *   REFUSED       - hostile case returned a documented non-zero code / safe
 *                   query result, and the dest canary is intact.
 *   CRASH         - child terminated by a signal (SIGSEGV/SIGABRT/SIGALRM...)
 *   CORRUPT       - child survived but the canary past `cap` was modified.
 *   UNEXPECTED_OK - child survived, canary intact, but the API reported
 *                   SUCCESS for a case where the contract promises refusal.
 *
 * Prints: REDTEAM memstr <cases> <refused> <crashes> <corrupt> <unexpected_ok>
 * Exits 0 if the harness completed (findings are reported, not hidden).
 */
#define _POSIX_C_SOURCE 200112L
#include <errno.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/resource.h>
#include <sys/wait.h>

typedef int errno_t;
typedef size_t rsize_t;

/* ---- target APIs (verified with nm against libcplus_safecrt.a) --------- */
extern errno_t cplus_sc_memcpy_s(void *, rsize_t, const void *, rsize_t);
extern errno_t cplus_sc_memmove_s(void *, rsize_t, const void *, rsize_t);
extern errno_t cplus_sc_memset_s(void *, rsize_t, int, rsize_t);
extern errno_t cplus_sc_memcmp_s(const void *, rsize_t, const void *, rsize_t, int *);
extern errno_t cplus_sc_memzero_s(void *, rsize_t);
extern errno_t cplus_sc_strcpy_s(char *, rsize_t, const char *);
extern errno_t cplus_sc_strncpy_s(char *, rsize_t, const char *, rsize_t);
extern errno_t cplus_sc_strcat_s(char *, rsize_t, const char *);
extern errno_t cplus_sc_strncat_s(char *, rsize_t, const char *, rsize_t);
extern errno_t cplus_sc_strcmp_s(const char *, rsize_t, const char *, int *);
extern rsize_t  cplus_sc_strnlen_s(const char *, rsize_t);
extern char    *cplus_sc_strtok_s(char *, rsize_t *, const char *, char **);

extern errno_t cplus_memcpy_s(void *, rsize_t, const void *, rsize_t);
extern errno_t cplus_memmove_s(void *, rsize_t, const void *, rsize_t);
extern errno_t cplus_memset_s(void *, rsize_t, int, rsize_t);
extern errno_t cplus_memcmp_s(const void *, rsize_t, const void *, rsize_t, int *);
extern errno_t cplus_memzero_s(void *, rsize_t);
extern errno_t cplus_strcpy_s(char *, rsize_t, const char *);
extern errno_t cplus_strncpy_s(char *, rsize_t, const char *, rsize_t);
extern errno_t cplus_strcat_s(char *, rsize_t, const char *);
extern errno_t cplus_strncat_s(char *, rsize_t, const char *, rsize_t);
extern errno_t cplus_strcmp_s(const char *, rsize_t, const char *, int *);
extern rsize_t  cplus_strnlen_s(const char *, rsize_t);
extern char    *cplus_strtok_s(char *, rsize_t *, const char *, char **);

extern void cplus_safe_set_constraint_mode(int);
extern void cplus_sc_set_mem_constraint_handler_s_wrapper(void (*)(const char *, void *, int));
extern void cplus_sc_set_str_constraint_handler_s_wrapper(void (*)(const char *, void *, int));

enum { A_MEMCPY, A_MEMMOVE, A_MEMSET, A_MEMCMP, A_MEMZERO,
       A_STRCPY, A_STRNCPY, A_STRCAT, A_STRNCAT, A_STRCMP,
       A_STRNLEN, A_STRTOK, NAPI = 12 };
enum { C_DMAX_ZERO, C_NULL_DEST, C_NULL_SRC, C_ONE_OVER, C_HUGE_N,
       C_HUGE_DMAX, C_OVERLAP, C_UNTERMINATED, C_DMAX_GT_CAP,
       C_DMAX_GT_CAP_ONE, C_VALUE_GT255, C_DIFF_NULL, C_EMBEDDED_NUL, NCAS = 13 };

static const char *API_NAMES[NAPI] = {
    "memcpy_s", "memmove_s", "memset_s", "memcmp_s", "memzero_s",
    "strcpy_s", "strncpy_s", "strcat_s", "strncat_s", "strcmp_s",
    "strnlen_s", "strtok_s"
};
static const char *CAS_NAMES[NCAS] = {
    "DMAX_ZERO", "NULL_DEST", "NULL_SRC", "ONE_OVER", "HUGE_N",
    "HUGE_DMAX", "OVERLAP", "UNTERMINATED", "DMAX_GT_CAP",
    "DMAX_GT_CAP_ONE", "VALUE_GT255", "DIFF_NULL", "EMBEDDED_NUL"
};

#define MAXBUF 320                 /* 256 live + 64 canary guard */
#define CAN    0xC3u

typedef struct {
    long long id;
    int fam, api, cas;
    size_t cap;
    rsize_t dm, n;
    unsigned long L, O;
    int value, extra;
} Case;

static void noop_handler(const char *m, void *p, int e) {
    (void)m; (void)p; (void)e;
}

/* Dispatch the target call.  Returns an int-ish rc; for pointer/count APIs the
 * caller wraps it (see run_child).  `is_query` marks strnlen/strtok. */
static long long call_api(int fam, int api, void *dp, const void *sp,
                          rsize_t dm, rsize_t n, int value, int *diff, int *ind,
                          rsize_t *dmaxp, char **tok, const char *delim) {
    switch (api) {
    case A_MEMCPY:
        return fam == 0 ? cplus_sc_memcpy_s(dp, dm, sp, n) : cplus_memcpy_s(dp, dm, sp, n);
    case A_MEMMOVE:
        return fam == 0 ? cplus_sc_memmove_s(dp, dm, sp, n) : cplus_memmove_s(dp, dm, sp, n);
    case A_MEMSET:
        return fam == 0 ? cplus_sc_memset_s(dp, dm, value, n) : cplus_memset_s(dp, dm, value, n);
    case A_MEMCMP:
        return fam == 0 ? cplus_sc_memcmp_s(dp, dm, sp, n, diff) : cplus_memcmp_s(dp, dm, sp, n, diff);
    case A_MEMZERO:
        return fam == 0 ? cplus_sc_memzero_s(dp, dm) : cplus_memzero_s(dp, dm);
    case A_STRCPY:
        return fam == 0 ? cplus_sc_strcpy_s((char *)dp, dm, (const char *)sp) : cplus_strcpy_s((char *)dp, dm, (const char *)sp);
    case A_STRNCPY:
        return fam == 0 ? cplus_sc_strncpy_s((char *)dp, dm, (const char *)sp, n) : cplus_strncpy_s((char *)dp, dm, (const char *)sp, n);
    case A_STRCAT:
        return fam == 0 ? cplus_sc_strcat_s((char *)dp, dm, (const char *)sp) : cplus_strcat_s((char *)dp, dm, (const char *)sp);
    case A_STRNCAT:
        return fam == 0 ? cplus_sc_strncat_s((char *)dp, dm, (const char *)sp, n) : cplus_strncat_s((char *)dp, dm, (const char *)sp, n);
    case A_STRCMP:
        return fam == 0 ? cplus_sc_strcmp_s((const char *)dp, dm, (const char *)sp, ind) : cplus_strcmp_s((const char *)dp, dm, (const char *)sp, ind);
    case A_STRNLEN:
        return fam == 0 ? (long long)cplus_sc_strnlen_s((const char *)sp, dm) : (long long)cplus_strnlen_s((const char *)sp, dm);
    case A_STRTOK: {
        char *r = fam == 0 ? cplus_sc_strtok_s((char *)dp, dmaxp, delim, tok)
                           : cplus_strtok_s((char *)dp, dmaxp, delim, tok);
        return r ? 1 : 0; /* 1 = token found, 0 = refusal/end */
    }
    default:
        return -999;
    }
}

/* Set up buffers per (api,cas) and execute.  Writes observed data to pipe. */
static void run_child(const Case *c, int wrfd) {
    unsigned char buf[MAXBUF], sbuf[MAXBUF];
    void *dp = buf;
    const void *sp = sbuf;
    int diff = -777, ind = -777;
    rsize_t dmaxp = c->dm;
    char *tok = NULL;
    const char *delim = " ";
    long long rc = -999;
    size_t i, srclen, off;
    int bad = -1;
    int outcome;

    cplus_safe_set_constraint_mode(0); /* IGNORE: refusals -> return codes */
    cplus_sc_set_mem_constraint_handler_s_wrapper(noop_handler);
    cplus_sc_set_str_constraint_handler_s_wrapper(noop_handler);
    alarm(3);                          /* watchdog: a hang is a CRASH */

    memset(buf, CAN, sizeof buf);
    memset(sbuf, 'A', sizeof sbuf);
    srclen = (size_t)(c->L % (c->cap + 1));
    sbuf[srclen < MAXBUF ? srclen : MAXBUF - 1] = 0;
    off = 1 + (size_t)(c->O % 8);

    /* Per-attack pointer / content setup.  dm and n come from the case. */
    switch (c->cas) {
    case C_NULL_DEST:
        dp = NULL;
        break;
    case C_NULL_SRC:
        sp = NULL;
        break;
    case C_ONE_OVER:
        if (c->api == A_STRCPY || c->api == A_STRCAT || c->api == A_STRCMP) {
            memset(sbuf, 'A', MAXBUF - 1); /* strlen(src) >> dmax */
            sbuf[MAXBUF - 1] = 0;
        }
        break;
    case C_OVERLAP:
        sp = buf + off;
        memset(buf + off, 'B', 12);
        buf[off + 12] = 0;
        break;
    case C_UNTERMINATED:
        memset(buf, 'A', c->cap); /* no NUL in [0,cap) */
        break;
    case C_DMAX_GT_CAP:
    case C_DMAX_GT_CAP_ONE:
        /* Wild-memset trigger: dmax>real cap + a self-detected violation. */
        sp = NULL;                 /* null src where the API has a src */
        if (c->api == A_MEMCPY || c->api == A_STRCPY || c->api == A_STRNCPY) {
            sp = buf + off;        /* overlap also triggers the wild memset */
            memset(buf + off, 'B', 12);
            buf[off + 12] = 0;
        }
        break;
    case C_EMBEDDED_NUL: {
        size_t pos = (size_t)(c->extra % MAXBUF);
        sbuf[pos] = 0;             /* embedded NUL inside the source */
        break;
    }
    default:
        break;
    }

    /* str* destination APIs need a NUL-terminated dest for non-abusive cases. */
    if ((c->api == A_STRCAT || c->api == A_STRNCAT || c->api == A_STRCMP) &&
        c->cas != C_UNTERMINATED && c->cas != C_NULL_DEST) {
        buf[0] = 0;
    }
    if (c->api == A_STRTOK) {
        dmaxp = c->dm;
        if (dmaxp > c->cap && dmaxp < 4096) dmaxp = (rsize_t)c->cap; /* keep token scan in-bounds */
        memcpy(buf, "aaa bbb ccc", 11);
        buf[11] = 0;
    }

    rc = call_api(c->fam, c->api, dp, sp, c->dm, c->n, c->value,
                  &diff, &ind, &dmaxp, &tok, delim);

    for (i = c->cap; i < MAXBUF; i++) {
        if (buf[i] != CAN) { bad = (int)i; break; }
    }
    if (bad >= 0) outcome = 1;                       /* CORRUPT */
    else if (c->api == A_STRNLEN || c->api == A_STRTOK) {
        /* query APIs: a non-zero result/token on a hostile case is OK-flagged */
        outcome = (rc == 0) ? 0 : 2;
    } else {
        outcome = (rc != 0) ? 0 : 2;                  /* errno_t: nonzero = refused */
    }

    {
        char line[256];
        int len = snprintf(line, sizeof line, "rc=%lld can=%d first_bad=%d\n",
                           rc, bad < 0, bad);
        if (len > 0) {
            if (len >= (int)sizeof line) len = (int)sizeof line - 1;
            (void)write(wrfd, line, (size_t)len);
        }
    }
    _exit(outcome == 0 ? 0 : (outcome == 1 ? 1 : 2));
}

static int parse_case(char *line, Case *c) {
    char *p = line;
    int f = 0;
    unsigned long long v[11];
    int i;
    for (i = 0; i < 11; i++) {
        char *end;
        while (*p == ' ' || *p == '\t') p++;
        if (!*p) return 0;
        errno = 0;
        v[i] = strtoull(p, &end, 10);
        if (errno || end == p) return 0;
        p = end;
    }
    c->id = (long long)v[0];
    c->fam = (int)v[1];
    c->api = (int)v[2];
    c->cas = (int)v[3];
    c->cap = (size_t)v[4];
    if (c->cap > 256) c->cap = 256;
    if (c->cap < 8) c->cap = 8;
    c->dm = (rsize_t)v[5];
    c->n = (rsize_t)v[6];
    c->L = (unsigned long)v[7];
    c->O = (unsigned long)v[8];
    c->value = (int)v[9];
    c->extra = (int)v[10];
    return 1;
}

int main(int argc, char **argv) {
    const char *casefile = "results/attack_cases.tsv";
    const char *logfile = "results/scenarios.log";
    char line[1024];
    FILE *fin, *flog;
    long long n_refused = 0, n_crash = 0, n_corrupt = 0, n_ok = 0, n_total = 0;
    struct rlimit rl = {0, 0};

    (void)argc; (void)argv;
    setrlimit(RLIMIT_CORE, &rl); /* never leave core dumps behind */

    fin = fopen(casefile, "r");
    if (!fin) { fprintf(stderr, "cannot open %s\n", casefile); return 70; }
    flog = fopen(logfile, "w");
    if (!flog) { fprintf(stderr, "cannot open %s\n", logfile); fclose(fin); return 70; }
    fprintf(flog, "# id fam api cas dm n cap outcome rc_line\n");

    while (fgets(line, sizeof line, fin)) {
        Case c;
        int pfd[2];
        pid_t pid;
        int st = 0;
        char observed[256] = "-";
        const char *outcome;
        if (line[0] == '#' || line[0] == '\n') continue;
        if (!parse_case(line, &c)) { fprintf(stderr, "bad case line\n"); continue; }

        if (pipe(pfd) != 0) { perror("pipe"); return 70; }
        pid = fork();
        if (pid < 0) { perror("fork"); return 70; }
        if (pid == 0) {
            close(pfd[0]);
            run_child(&c, pfd[1]);
            _exit(3); /* unreachable */
        }
        close(pfd[1]);
        {
            ssize_t got = read(pfd[0], observed, sizeof observed - 1);
            if (got > 0) { observed[got] = 0; if (observed[got-1] == '\n') observed[got-1] = 0; }
            else observed[0] = 0;
        }
        close(pfd[0]);
        waitpid(pid, &st, 0);

        if (WIFSIGNALED(st)) {
            outcome = "CRASH";
            n_crash++;
            snprintf(observed, sizeof observed, "signal=%d", WTERMSIG(st));
        } else if (WEXITSTATUS(st) == 1) {
            outcome = "CORRUPT"; n_corrupt++;
        } else if (WEXITSTATUS(st) == 2) {
            outcome = "UNEXPECTED_OK"; n_ok++;
        } else if (WEXITSTATUS(st) == 0) {
            outcome = "REFUSED"; n_refused++;
        } else {
            outcome = "SKIP";
        }
        n_total++;

        fprintf(flog, "%lld %d %s %s %llu %llu %zu %s [%s]\n",
                c.id, c.fam, API_NAMES[c.api], CAS_NAMES[c.cas],
                (unsigned long long)c.dm, (unsigned long long)c.n, c.cap,
                outcome, observed);
        if (strcmp(outcome, "CRASH") == 0 || strcmp(outcome, "CORRUPT") == 0 ||
            strcmp(outcome, "UNEXPECTED_OK") == 0) {
            fprintf(stderr, "FINDING id=%lld fam=%d api=%s cas=%s dm=%llu n=%llu cap=%zu %s [%s]\n",
                    c.id, c.fam, API_NAMES[c.api], CAS_NAMES[c.cas],
                    (unsigned long long)c.dm, (unsigned long long)c.n, c.cap,
                    outcome, observed);
        }
    }
    fclose(fin);
    fclose(flog);

    printf("REDTEAM memstr %lld %lld %lld %lld %lld\n",
           n_total, n_refused, n_crash, n_corrupt, n_ok);
    return 0; /* harness ran; findings are reported, not hidden */
}
